'use client';
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent } from 'react';
import SplitLineReveal from '../../../effects/split-line-reveal';
import { meta as splitMeta } from '../../../effects/split-line-reveal/meta';
import { spring as SPRING, springToLinear, useElementSize, useScrollProgress, useStudioMotion } from '../../../motion';
import { StudioCanvas, defaultQualityProfiles, describeModelError, detectCapabilities, resolveModelUrl, resolveModelVariant, useModelManifest, type QualityLevel } from '../../../three';
import type { EffectMeta, ParamValues } from '../../../types';
import { Director, type DialApi, type PointerLight } from './Director';
import { MagneticPill } from './MagneticPill';
import { VOLUME } from './stage';
import styles from './styles.module.css';

const MANIFEST_URL = '/models/pulse-speaker.manifest.json';
const POSTER = '/models/pulse-speaker.webp';
const defaults = (m: EffectMeta): ParamValues => Object.fromEntries(m.params.map((p) => [p.key, p.default]));
const BEATS = [
  { id: 'night', label: 'Night' },
  { id: 'sound', label: 'Sound' },
  { id: 'dial', label: 'Dial' },
] as const;
/** Below this width the copy stacks under the speaker (a card at the bottom of each chapter). */
const STACK_BELOW = 768;

export default function CinematicLanding() {
  const { reduced } = useStudioMotion();
  const root = useRef<HTMLDivElement>(null);
  const scene = useRef<HTMLElement>(null);
  const sticky = useRef<HTMLDivElement>(null);
  const beatEls = useRef<(HTMLElement | null)[]>([]);
  const progress = useRef(0);
  const invalidateRef = useRef<(() => void) | null>(null);
  const pointer = useRef<PointerLight>({ x: 0, y: 0, inside: false });
  const dialRef = useRef<DialApi | null>(null);
  const [webgl, setWebgl] = useState<boolean | null>(null);
  const [skip, setSkip] = useState(0);
  const [introDone, setIntroDone] = useState(false);
  const [ambience, setAmbience] = useState(true);
  const [beat, setBeat] = useState(0);
  const [level, setLevel] = useState<QualityLevel | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [volume, setVolume] = useState<number>(VOLUME.start);
  const [announced, setAnnounced] = useState('');
  const { width } = useElementSize(root);
  const stacked = width > 0 && width < STACK_BELOW;

  useEffect(() => { setWebgl(detectCapabilities().webgl); }, []);
  const { manifest } = useModelManifest(MANIFEST_URL);
  const variant = manifest && level ? resolveModelVariant(manifest, defaultQualityProfiles[level].modelVariant) : null;
  const url = variant ? resolveModelUrl(variant.file, MANIFEST_URL) : null;

  useScrollProgress(scene, (p) => {
    progress.current = p;
    invalidateRef.current?.();
    const b = Math.min(BEATS.length - 1, Math.round(p * (BEATS.length - 1)));
    setBeat((prev) => (prev === b ? prev : b));
  }, { mode: 'contain' });

  // Screen readers hear the volume once the dial comes to rest, not every notch.
  useEffect(() => {
    const t = window.setTimeout(() => setAnnounced(`Volume ${volume} of ${VOLUME.max}`), 450);
    return () => window.clearTimeout(t);
  }, [volume]);

  const onIntroDone = useCallback(() => setIntroDone(true), []);
  const onLoaded = useCallback(() => setLoaded(true), []);
  const onVolume = useCallback((v: number) => setVolume(v), []);
  // The scene's key light, handed to CSS: the angle the copy is lit from, and where the speaker stands.
  const onLight = useCallback((angle: number, subjectX: number) => {
    const el = root.current;
    if (!el) return;
    el.style.setProperty('--light-angle', `${angle.toFixed(1)}deg`);
    el.style.setProperty('--subject-x', `${(subjectX * 100).toFixed(1)}%`);
  }, []);
  const live = webgl === true && !error;
  const introRunning = live && !reduced && !introDone;
  const goTo = (i: number) => beatEls.current[i]?.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
  const stepVolume = (d: number) => {
    if (dialRef.current && live) dialRef.current.step(d);
    else setVolume((v) => Math.min(VOLUME.max, Math.max(0, v + d)));
  };

  const onPointerMove = (e: ReactPointerEvent<HTMLElement>) => {
    if (e.pointerType === 'touch' || reduced) return;
    const r = sticky.current?.getBoundingClientRect();
    if (!r || r.width === 0) return;
    pointer.current = {
      x: Math.max(-1, Math.min(1, ((e.clientX - r.left) / r.width) * 2 - 1)),
      y: Math.max(-1, Math.min(1, ((e.clientY - r.top) / r.height) * 2 - 1)),
      inside: e.clientY >= r.top && e.clientY <= r.bottom,
    };
    invalidateRef.current?.();
  };
  const onPointerLeave = () => { pointer.current = { ...pointer.current, inside: false }; invalidateRef.current?.(); };

  // Every pressable control releases on the same spring (CSS linear() sampled from the `press` token).
  const release = useMemo(() => springToLinear(SPRING.press), []);
  const rootStyle = { '--release-ease': release.easing, '--release-dur': `${release.duration}ms` } as CSSProperties;

  return (
    <div ref={root} data-stage="ink" data-beat={beat} data-layout={stacked ? 'stacked' : 'split'} data-reduced={reduced || undefined} className={`${styles.root} text-ink`} style={rootStyle}>
      <section ref={scene} className={styles.scene} aria-label="Pulse Night Edition" onPointerMove={onPointerMove} onPointerLeave={onPointerLeave}>
        <div ref={sticky} className={styles.sticky}>
          <StudioCanvas
            label="The Pulse speaker, night edition, on a stone plinth"
            description="A compact charcoal speaker with an orange dial and trim ring stands on a dark stone plinth under one warm key light and a cool rim light; a cyan ring around the dial glows softly. Scrolling moves the camera from a three-quarter view to the grille and then up over the dial, where the room goes dark and the ring lights the dial. The key light leans towards the pointer; dragging turns the speaker."
            frameloop={!reduced && ambience ? 'always' : 'demand'}
            onQualityChange={setLevel}
            onSceneError={setError}
            camera={{ fov: 22, near: 0.1, far: 60, position: [-9, 1.2, 8] }}
            style={{ position: 'absolute', inset: 0 }}
            fallback={<img src={POSTER} alt="Studio render of the Pulse speaker in graphite and ember" className={styles.poster} />}
          >
            {url ? (
              <Director
                progress={progress} invalidateRef={invalidateRef} pointer={pointer} dialRef={dialRef} stacked={stacked}
                skip={skip} playIntro={!reduced} ambience={ambience} reduced={reduced}
                onIntroDone={onIntroDone} onLoaded={onLoaded} onError={setError} onVolume={onVolume} onLight={onLight} variantUrl={url}
              />
            ) : null}
          </StudioCanvas>
          {error ? (
            <div className="absolute inset-0">
              <img src={POSTER} alt="Studio render of the Pulse speaker in graphite and ember" className={styles.poster} />
              <p role="alert" className="absolute bottom-4 right-4 m-0 max-w-[24rem] rounded-[6px] border border-line bg-surface p-3 text-[13px]">{describeModelError(error)} Showing the still render.</p>
            </div>
          ) : null}
          {live && !loaded ? <p className={`mk-label ${styles.loading}`} role="status">Loading the speaker…</p> : null}
        </div>

        <div className={styles.beats}>
          <div className={styles.chrome}>
            <div className={styles.chromeRow}>
              <p className="mk-label m-0 text-ink">kiln<span className="text-signal">.</span>audio <span className="text-muted">/ night edition</span></p>
              <div className="flex items-center gap-2">
                {introRunning ? (
                  <MagneticPill onClick={() => setSkip((n) => n + 1)}>Skip intro</MagneticPill>
                ) : live && !reduced ? (
                  <MagneticPill onClick={() => setAmbience((a) => !a)}>{ambience ? 'Pause light' : 'Play light'}</MagneticPill>
                ) : null}
              </div>
            </div>
            <nav aria-label="Sections" className={styles.nav}>
              {BEATS.map((b, i) => (
                <button key={b.id} type="button" className={styles.navItem} aria-current={beat === i ? 'step' : undefined} onClick={() => goTo(i)}>
                  <span className="font-mono text-[11px]">{String(i + 1).padStart(2, '0')}</span> {b.label}
                </button>
              ))}
            </nav>
          </div>

          <article ref={(el) => { beatEls.current[0] = el; }} className={styles.beat}>
            <div className={styles.copy}>
              <p className="mk-label m-0 text-muted">Pulse · Night Edition · fictional</p>
              <div className={styles.headline}>
                <SplitLineReveal params={{ ...defaults(splitMeta), text: 'Built for the hour after midnight.', stagger: 64, duration: 980, rise: 105, skew: true }} />
              </div>
              <p className={styles.body}>
                Graphite and ember, with a status ring that breathes while it plays. One dial, no screen, nothing to set up at one in the morning.
              </p>
              <p className={`mk-label ${styles.hint}`}><span aria-hidden="true" className={styles.rule} />Scroll to look closer · drag to turn it</p>
            </div>
          </article>

          <article ref={(el) => { beatEls.current[1] = el; }} className={`${styles.beat} ${styles.beatRight}`}>
            <div className={styles.copy}>
              <p className={styles.eyebrow}>01 — The sound</p>
              <h3 className={styles.title}>Small room, <span className="font-serif font-normal italic">full voice.</span></h3>
              <p className={styles.body}>
                A single 52 mm driver behind a perforated grille, tuned for voices and late playlists. It plays quietly without thinning out.
              </p>
            </div>
          </article>

          <article ref={(el) => { beatEls.current[2] = el; }} className={styles.beat}>
            <div className={styles.copy}>
              <p className={styles.eyebrow}>02 — The dial</p>
              <h3 className={styles.title}>Turn it. <span className="font-serif font-normal italic">That’s all.</span></h3>
              <p className={styles.body}>
                Turn for volume, press to pause. The ring beneath the dial glows while it is paired — the only light it makes in a dark room.
              </p>
              <div className={styles.dialRow} role="group" aria-label="Volume dial">
                <button type="button" className={styles.key} aria-label="Turn the dial down" onClick={() => stepVolume(-1)} disabled={volume <= 0}>
                  <span className={styles.keyFace} aria-hidden="true">−</span>
                </button>
                <p className={styles.readout} aria-hidden="true">
                  <span className={styles.readoutValue}>{String(volume).padStart(2, '0')}</span>
                  <span className={styles.meter}><span style={{ transform: `scaleX(${volume / VOLUME.max})` }} /></span>
                </p>
                <button type="button" className={styles.key} aria-label="Turn the dial up" onClick={() => stepVolume(1)} disabled={volume >= VOLUME.max}>
                  <span className={styles.keyFace} aria-hidden="true">+</span>
                </button>
                <p className="mk-sr-only" role="status">{announced}</p>
              </div>
              <p className={`mk-label ${styles.hint}`}>{live ? 'Drag the dial or use ← → · ' : ''}no sound, Pulse is fictional</p>
            </div>
          </article>
        </div>
      </section>

      <section className="mx-auto max-w-[1280px] px-4 pb-24 pt-16 @3xl:px-8" aria-labelledby="night-specs">
        <div className="grid gap-8 border-t border-line-strong pt-6 @4xl:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]">
          <h3 id="night-specs" className="m-0 font-serif text-[clamp(2rem,6cqi,3.4rem)] font-normal italic leading-none">The small print.</h3>
          <div>
            <dl className="m-0 grid grid-cols-1 gap-x-8 @xl:grid-cols-2">
              {[['Size', '223 × 144 × 85 mm'], ['Driver', 'One 52 mm full-range'], ['Controls', 'One knurled dial, 30 detents'], ['Light', 'Status ring, paired only'], ['Finish', 'Graphite shell, ember hardware'], ['Price', 'Not for sale — Pulse is fictional']].map(([k, v]) => (
                <div key={k} className="flex items-baseline justify-between gap-4 border-b border-line py-2.5 text-[14px]">
                  <dt className="text-muted">{k}</dt><dd className="m-0 text-right">{v}</dd>
                </div>
              ))}
            </dl>
            <p className="m-0 mt-5 text-[13.5px] leading-relaxed text-muted">
              Want it in another colour? <a href="/demos/3d/product-configurator" className={styles.link}>Open the configurator</a>. Without WebGL this page shows the same copy over a still render; with reduced motion the camera skips the opening move, cuts between chapters and the light holds still.
            </p>
          </div>
        </div>
      </section>
    </div>
  );
}

'use client';
/**
 * The Pulse Night scene and its director. One camera, one key light, one pair of hands:
 *  - camera: an opening arc (rim light first, then the key) that ends on chapter 01; then scroll drives it between
 *    three held shots (spherical arcs, lens-shifted so the speaker sits opposite the copy); a ±3° sway follows the
 *    pointer. Reduced motion: no opening, cuts between chapters, no sway.
 *  - light: the key orbits towards the pointer (and drifts slowly on its own while the light plays); the generated
 *    environment turns with it, and the same angle is written to CSS so the headline is lit from the same side.
 *  - hands: drag (or ←/→ on the focused canvas) turns the speaker on its plinth; it keeps the release velocity and
 *    springs back to the chapter's pose on the heavy `glide` spring. In the dial chapter the same gesture turns the
 *    dial through 30 detents; the small dial snaps into its notch on the quick `press` spring.
 * Everything settles and stops requesting frames; with the light paused the canvas renders on demand.
 */
import { useFrame, useThree } from '@react-three/fiber';
import { Suspense, useCallback, useEffect, useMemo, useRef, useState, type MutableRefObject } from 'react';
import { MathUtils, Object3D, type Group, type Mesh, type MeshStandardMaterial, type PerspectiveCamera, type PointLight, type SpotLight } from 'three';
import { duration, sec, spring as SPRING, stepSpring } from '../../../motion';
import {
  AnimationPlayer, LightingRig, Model, ModelBoundary, PartController, useQuality, useStudioCanvasHost,
  type AnimationPlayerHandle, type LightingRigHandle, type LoadedModel, type PartControllerCore,
} from '../../../three';
import {
  DETENT, INTRO_FROM, KEY_ORBIT, LIGHT_SWING, NIGHT, REFERENCE_ASPECT, RING_LIGHT, SHADOW_PLANE, SWAY_DEG, VOLUME,
  atRest, blendLight, buildContactShadow, buildPlinthGeometry, buildStoneTextures, damp, detented, introShot,
  releaseVelocity, shotForProgress, smooth, softLimit, volumeAt, type Axis, type Framing, type Light, type Shot,
} from './stage';

/** The opening move: 2.5 × the `epic` token (3.5 s), skippable, and it only starts once the speaker is on stage. */
const INTRO_S = sec(duration.epic * 2.5);
/** Radians of turn for a drag across the whole canvas; radians of dial per pixel. */
const TURN_PER_WIDTH = 2.4;
const DIAL_PER_PX = 0.0085;
/** The speaker turns freely to ±0.6 rad, then rubber-bands towards ±1 rad. */
const TURN_FREE = 0.6, TURN_LIMIT = 1.0;
/** Dial end stops: volume 0 and 30. */
const DIAL_MIN = -(VOLUME.max - VOLUME.start) * DETENT, DIAL_MAX = VOLUME.start * DETENT;
/** The ring's own light sits at ring level, inside the dial: it reaches the shell around it, never the dial's top. */
const KNOB_LIGHT = { position: [0.55, 1.05, 0] as const };
const SPOT_INTENSITY = 3.6;

export interface PointerLight { x: number; y: number; inside: boolean }
export interface DialApi { step(detents: number): void }

export interface DirectorProps {
  /** Scroll progress through the pinned section, 0..1 (written by the page, read every frame). */
  progress: MutableRefObject<number>;
  /** Set by the scene so the page can request a frame (render on demand when the light is paused). */
  invalidateRef: MutableRefObject<(() => void) | null>;
  /** Pointer position over the stage, -1..1, written by the page. */
  pointer: MutableRefObject<PointerLight>;
  /** The page's volume buttons call into the dial through this. */
  dialRef: MutableRefObject<DialApi | null>;
  /** Stacked (narrow) layout: the copy card sits at the bottom, so the speaker is framed in the top half. */
  stacked: boolean;
  skip: number;
  playIntro: boolean;
  ambience: boolean;
  reduced: boolean;
  onIntroDone: () => void;
  onLoaded: () => void;
  onError: (e: Error) => void;
  onVolume: (v: number) => void;
  /** The shared light, for CSS: the angle the copy is lit from and the speaker's x position (0..1) on screen. */
  onLight: (angleDeg: number, subjectX: number) => void;
  variantUrl: string;
}

const newShot = (): Shot => ({ az: 0, el: 0, dist: 1, fx: 0, fy: 0, fz: 0, fov: 30, sx: 0, sy: 0, turn: 0 });
const SHOT_KEYS = ['az', 'el', 'dist', 'fx', 'fy', 'fz', 'fov', 'sx', 'sy', 'turn'] as const;
/** How close (per parameter) counts as arrived, so the demand loop can stop. */
const SHOT_EPS: Record<(typeof SHOT_KEYS)[number], number> = { az: 0.01, el: 0.01, dist: 1e-3, fx: 1e-4, fy: 1e-4, fz: 1e-4, fov: 1e-3, sx: 1e-5, sy: 1e-5, turn: 0.01 };

export function Director({
  progress, invalidateRef, pointer, dialRef, stacked, skip, playIntro, ambience, reduced,
  onIntroDone, onLoaded, onError, onVolume, onLight, variantUrl,
}: DirectorProps) {
  const camera = useThree((s) => s.camera) as PerspectiveCamera;
  const gl = useThree((s) => s.gl);
  const scene = useThree((s) => s.scene);
  const invalidate = useThree((s) => s.invalidate);
  const quality = useQuality();
  const host = useStudioCanvasHost();
  const lights = useRef<LightingRigHandle>(null);
  const spot = useRef<SpotLight>(null);
  const ringLight = useRef<PointLight>(null);
  const turntable = useRef<Group>(null);
  const player = useRef<AnimationPlayerHandle>(null);
  const ring = useRef<MeshStandardMaterial | null>(null);
  const knob = useRef<{ node: Object3D; base: number } | null>(null);
  const spotTarget = useMemo(() => new Object3D(), []);
  const [loaded, setLoaded] = useState(false);

  const s = useRef({
    phase: (playIntro && !reduced ? 'intro' : 'follow') as 'intro' | 'follow',
    introT: 0, time: 0, placed: false,
    cam: newShot(), goal: newShot(), from: newShot(),
    vel: Object.fromEntries(SHOT_KEYS.map((k) => [k, { v: 0 }])) as Record<(typeof SHOT_KEYS)[number], { v: number }>,
    light: { x: 0, y: 0, vx: { v: 0 }, vy: { v: 0 } },
    weights: [1, 0, 0] as [number, number, number],
    plan: { key: 1, keyAz: 0, rim: 1, env: 1, spot: 0, ring: 1 } as Light,
    yaw: { x: 0, v: 0 } as Axis,
    dial: { x: 0, v: 0 } as Axis, dialTarget: 0, volume: VOLUME.start, flash: 0, held: 0,
    drag: null as null | { id: number; mode: 'turn' | 'dial'; x0: number; start: number; samples: { t: number; x: number }[] },
    out: { angle: -999, sx: -999 }, view: { w: 0, h: 0, sx: -999, sy: -999 },
  });
  const live = useRef({ reduced, ambience, stacked, playIntro, loaded, onIntroDone, onVolume, onLight });
  live.current = { reduced, ambience, stacked, playIntro, loaded, onIntroDone, onVolume, onLight };
  invalidateRef.current = invalidate;

  const endIntro = useCallback((smoothHandover: boolean) => {
    const st = s.current;
    if (st.phase !== 'intro') return;
    st.phase = 'follow';
    for (const k of SHOT_KEYS) st.vel[k].v = 0;
    st.placed = smoothHandover && st.introT > 0;
    st.introT = 1;
    live.current.onIntroDone();
  }, []);
  // Skip: cut to the held shot for the current scroll position.
  useEffect(() => { if (skip) { endIntro(false); s.current.placed = false; invalidate(); } }, [skip, endIntro, invalidate]);
  useEffect(() => { if (reduced) { endIntro(false); s.current.placed = false; } invalidate(); }, [reduced, endIntro, invalidate]);
  useEffect(() => { invalidate(); }, [stacked, ambience, invalidate]);

  // The ring's breathing clip plays with the light, never under reduced motion.
  useEffect(() => {
    const p = player.current;
    if (!p) return;
    if (ambience && !reduced) p.play(); else p.pause();
    invalidate();
  }, [ambience, reduced, invalidate, loaded]);

  // The key light casts a real shadow on the plinth where the profile allows shadow maps.
  useEffect(() => {
    const key = lights.current?.key;
    if (!key) return;
    key.castShadow = quality.shadows;
    key.shadow.radius = 5;
    invalidate();
    return () => { key.castShadow = false; };
  }, [quality.shadows, invalidate]);

  // The environment turns with the key light; restore what was there before.
  useEffect(() => {
    const prev = scene.environmentRotation.y;
    return () => { scene.environmentRotation.y = prev; };
  }, [scene]);

  // The dial, for the page's volume buttons.
  const stepDial = useCallback((n: number) => {
    const st = s.current;
    st.dialTarget = MathUtils.clamp(Math.round(st.dialTarget / DETENT - n) * DETENT, DIAL_MIN, DIAL_MAX);
    if (live.current.reduced) { st.dial.x = st.dialTarget; st.dial.v = 0; }
    invalidate();
  }, [invalidate]);
  useEffect(() => {
    dialRef.current = { step: stepDial };
    return () => { dialRef.current = null; };
  }, [dialRef, stepDial]);

  // Hands: drag on the canvas turns the speaker (or the dial), ←/→ on the focused canvas do the same.
  useEffect(() => {
    const el = gl.domElement;
    const st = s.current;
    const inDial = () => Math.round(progress.current * 2) === 2;
    const down = (e: PointerEvent) => {
      if (e.pointerType === 'mouse' && e.button !== 0) return;
      const mode = inDial() ? 'dial' : 'turn';
      st.drag = { id: e.pointerId, mode, x0: e.clientX, start: mode === 'dial' ? st.dial.x : st.yaw.x, samples: [] };
      if (mode === 'dial') st.dialTarget = st.dial.x;
      try { el.setPointerCapture(e.pointerId); } catch { /* pointer already gone */ }
      el.dataset.dragging = '';
      invalidate();
    };
    const move = (e: PointerEvent) => {
      const d = st.drag;
      if (!d || d.id !== e.pointerId) return;
      const dx = e.clientX - d.x0;
      const t = performance.now();
      if (d.mode === 'turn') {
        // 1:1 with the hand, then a rubber band towards the limit (what you see is what gets thrown)
        st.yaw.x = softLimit(d.start + (dx / Math.max(1, el.clientWidth)) * TURN_PER_WIDTH, TURN_FREE, TURN_LIMIT);
        st.yaw.v = 0;
        d.samples.push({ t, x: st.yaw.x });
      } else {
        const raw = d.start - dx * DIAL_PER_PX;
        // end stops with a little give
        st.dial.x = raw > DIAL_MAX ? DIAL_MAX + softLimit(raw - DIAL_MAX, 0, DETENT * 0.6) : raw < DIAL_MIN ? DIAL_MIN + softLimit(raw - DIAL_MIN, 0, DETENT * 0.6) : raw;
        st.dial.v = 0;
        d.samples.push({ t, x: st.dial.x });
      }
      if (d.samples.length > 12) d.samples.shift();
      invalidate();
    };
    const up = (e: PointerEvent) => {
      const d = st.drag;
      if (!d || d.id !== e.pointerId) return;
      st.drag = null;
      delete el.dataset.dragging;
      const v = e.type === 'pointercancel' ? 0 : releaseVelocity(d.samples, performance.now());
      if (d.mode === 'turn') st.yaw.v = MathUtils.clamp(v, -8, 8);
      else {
        // The dial keeps a little of its spin, then drops into the nearest notch.
        st.dial.x = detented(st.dial.x);
        st.dial.v = MathUtils.clamp(v, -12, 12);
        st.dialTarget = MathUtils.clamp(Math.round((st.dial.x + st.dial.v * 0.09) / DETENT) * DETENT, DIAL_MIN, DIAL_MAX);
      }
      if (live.current.reduced) { st.yaw.x = 0; st.yaw.v = 0; st.dial.x = st.dialTarget; st.dial.v = 0; }
      invalidate();
    };
    const key = (e: KeyboardEvent) => {
      if (e.altKey || e.ctrlKey || e.metaKey) return;
      const dir = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
      if (!dir) return;
      e.preventDefault();
      if (inDial()) { stepDial(dir); return; }
      if (live.current.reduced) { st.yaw.x = dir * 0.55; st.yaw.v = 0; st.held = dir; }
      else st.yaw.v = MathUtils.clamp(st.yaw.v + dir * 3.2, -6, 6);
      invalidate();
    };
    const keyUp = (e: KeyboardEvent) => {
      if (st.held && (e.key === 'ArrowRight' || e.key === 'ArrowLeft')) { st.held = 0; st.yaw.x = 0; invalidate(); }
    };
    // A focusable canvas is a control: name it, describe its keys, and make the StudioCanvas wrapper a group.
    const prev = { tabIndex: el.getAttribute('tabindex'), role: el.getAttribute('role'), label: el.getAttribute('aria-label'), keys: el.getAttribute('aria-keyshortcuts') };
    el.tabIndex = 0;
    el.setAttribute('role', 'application');
    el.setAttribute('aria-label', 'Pulse speaker on its plinth. Drag sideways or press the left and right arrow keys to turn it; in the Dial chapter they turn the volume dial.');
    el.setAttribute('aria-keyshortcuts', 'ArrowLeft ArrowRight');
    el.style.touchAction = 'pan-y';
    const release = host?.requestInteractive();
    el.addEventListener('pointerdown', down);
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up);
    el.addEventListener('pointercancel', up);
    el.addEventListener('lostpointercapture', up);
    el.addEventListener('keydown', key);
    el.addEventListener('keyup', keyUp);
    return () => {
      el.removeEventListener('pointerdown', down);
      el.removeEventListener('pointermove', move);
      el.removeEventListener('pointerup', up);
      el.removeEventListener('pointercancel', up);
      el.removeEventListener('lostpointercapture', up);
      el.removeEventListener('keydown', key);
      el.removeEventListener('keyup', keyUp);
      prev.tabIndex === null ? el.removeAttribute('tabindex') : el.setAttribute('tabindex', prev.tabIndex);
      prev.role === null ? el.removeAttribute('role') : el.setAttribute('role', prev.role);
      prev.label === null ? el.removeAttribute('aria-label') : el.setAttribute('aria-label', prev.label);
      prev.keys === null ? el.removeAttribute('aria-keyshortcuts') : el.setAttribute('aria-keyshortcuts', prev.keys);
      el.style.touchAction = '';
      release?.();
    };
  }, [gl, host, progress, invalidate, stepDial]);

  useFrame((state, rawDt) => {
    const st = s.current;
    const L = live.current;
    const dt = Math.min(rawDt, 1 / 20);
    const { width, height } = state.size;
    const frame: Framing = L.stacked ? 'tall' : 'wide';
    const corr = Math.max(1, REFERENCE_ASPECT[frame] / Math.max(0.1, width / Math.max(1, height)));
    shotForProgress(progress.current, frame, L.reduced, st.goal, st.weights);
    st.goal.dist *= corr;
    const animated = L.ambience && !L.reduced;
    if (animated) st.time += dt;
    let busy = false;

    // ── Camera ────────────────────────────────────────────────────────────────────────────────────────
    let rimIn = 1, keyIn = 1, ringIn = 1;
    if (st.phase === 'intro') {
      if (!L.playIntro || L.reduced) endIntro(false);
      else if (progress.current > 0.015) endIntro(true);
      else {
        if (L.loaded) st.introT = Math.min(1, st.introT + dt / INTRO_S);
        Object.assign(st.from, INTRO_FROM[frame]);
        st.from.dist *= corr;
        introShot(st.introT, st.from, st.goal, st.cam);
        // The reveal: the rim draws the silhouette first, then the key comes up, then the ring.
        rimIn = smooth(st.introT / 0.35); keyIn = smooth((st.introT - 0.18) / 0.5); ringIn = smooth((st.introT - 0.55) / 0.4);
        busy = true;
        if (st.introT >= 1) endIntro(true);
      }
    }
    if (st.phase === 'follow') {
      if (L.reduced || !st.placed) {
        Object.assign(st.cam, st.goal);
        for (const k of SHOT_KEYS) st.vel[k].v = 0;
        st.placed = true;
      } else {
        for (const k of SHOT_KEYS) {
          st.cam[k] = damp(st.cam[k], st.goal[k], st.vel[k], k === 'sx' || k === 'sy' ? 0.7 : 0.62, dt);
          if (Math.abs(st.cam[k] - st.goal[k]) > SHOT_EPS[k] || Math.abs(st.vel[k].v) > SHOT_EPS[k] * 4) busy = true;
        }
      }
    }

    // ── The shared light: pointer (or the slow drift while the light plays) ─────────────────────────────
    const P = pointer.current;
    const drift = animated ? 0.62 * Math.sin(st.time * 0.21) + 0.2 * Math.sin(st.time * 0.53 + 1.3) : 0;
    const tx = L.reduced ? 0 : P.inside ? P.x : drift;
    const ty = L.reduced ? 0 : P.inside ? P.y : 0;
    st.light.x = damp(st.light.x, tx, st.light.vx, 0.38, dt);
    st.light.y = damp(st.light.y, ty, st.light.vy, 0.38, dt);
    if (Math.abs(st.light.x - tx) > 1e-3 || Math.abs(st.light.y - ty) > 1e-3 || Math.abs(st.light.vx.v) > 4e-3) busy = true;

    const c = st.cam;
    const az = MathUtils.degToRad(c.az + st.light.x * SWAY_DEG.az * (L.reduced ? 0 : 1));
    const el = MathUtils.degToRad(c.el - st.light.y * SWAY_DEG.el * (L.reduced ? 0 : 1));
    camera.position.set(c.fx + c.dist * Math.cos(el) * Math.sin(az), c.fy + c.dist * Math.sin(el), c.fz + c.dist * Math.cos(el) * Math.cos(az));
    camera.lookAt(c.fx, c.fy, c.fz);
    const v = st.view;
    if (Math.abs(camera.fov - c.fov) > 1e-4 || v.w !== width || v.h !== height || v.sx !== c.sx || v.sy !== c.sy) {
      camera.fov = c.fov;
      v.w = width; v.h = height; v.sx = c.sx; v.sy = c.sy;
      // Lens shift: slide the projection window so the speaker sits opposite the copy (no keystoning).
      camera.setViewOffset(width, height, -c.sx * width, c.sy * height, width, height);
    }

    // ── Hands: the speaker's turn and the dial ─────────────────────────────────────────────────────────
    const yaw = st.yaw;
    if (!st.drag || st.drag.mode !== 'turn') {
      if (L.reduced) { if (!st.held) { yaw.x = 0; yaw.v = 0; } }
      else if (!atRest(yaw, 0)) { stepSpring(yaw, 0, SPRING.glide, dt); busy = true; } else { yaw.x = 0; yaw.v = 0; }
    }
    // The chapter's pose on the plinth (scrubbed with the camera) plus whatever the hand adds.
    if (turntable.current) turntable.current.rotation.y = MathUtils.degToRad(st.cam.turn) + yaw.x;

    const dial = st.dial;
    let shown = dial.x;
    if (st.drag?.mode === 'dial') shown = detented(dial.x);
    else if (!atRest(dial, st.dialTarget, 2e-4)) { stepSpring(dial, st.dialTarget, SPRING.press, dt); shown = dial.x; busy = true; }
    else { dial.x = st.dialTarget; dial.v = 0; shown = dial.x; }
    if (knob.current) knob.current.node.rotation.y = knob.current.base + shown;
    const vol = volumeAt(shown);
    if (vol !== st.volume) { st.volume = vol; if (!L.reduced) st.flash = 0.7; L.onVolume(vol); }
    if (st.flash > 1e-3) { st.flash *= Math.exp(-dt / 0.14); busy = true; } else st.flash = 0;

    // ── Lights ─────────────────────────────────────────────────────────────────────────────────────────
    const plan = blendLight(st.weights, st.plan);
    const swing = st.light.x * LIGHT_SWING.az + plan.keyAz;
    const rig = lights.current;
    if (rig?.key) {
      const kAz = KEY_ORBIT.az + swing, kEl = KEY_ORBIT.el - st.light.y * LIGHT_SWING.el;
      rig.key.position.set(Math.sin(kAz) * Math.cos(kEl) * KEY_ORBIT.r, Math.sin(kEl) * KEY_ORBIT.r, Math.cos(kAz) * Math.cos(kEl) * KEY_ORBIT.r);
      rig.key.intensity = NIGHT.key.intensity * plan.key * keyIn;
    }
    if (rig?.rim && NIGHT.rim) rig.rim.intensity = NIGHT.rim.intensity * plan.rim * rimIn;
    if (rig?.fill && NIGHT.fill) rig.fill.intensity = NIGHT.fill.intensity * keyIn * (1 - 0.6 * st.weights[2]);
    scene.environmentRotation.y = swing;
    scene.environmentIntensity = NIGHT.env.intensity * plan.env * (0.25 + 0.75 * keyIn);
    if (spot.current) {
      spot.current.intensity = SPOT_INTENSITY * plan.spot * keyIn;
      // the spot finds the dial wherever the turntable has put it
      if (knob.current && plan.spot > 0) {
        knob.current.node.getWorldPosition(spotTarget.position);
        spot.current.position.set(spotTarget.position.x + 1.1, spotTarget.position.y + 3.6, spotTarget.position.z + 1.9);
        spotTarget.updateMatrixWorld();
      }
    }
    const breath = animated ? 0.5 + 0.5 * Math.sin(st.time * 2.2) : 0.55;
    const glow = ((1.15 + 0.95 * breath) * (0.7 + 0.6 * (st.volume / VOLUME.max)) * plan.ring + st.flash) * ringIn;
    if (ring.current) ring.current.emissiveIntensity = glow;
    if (ringLight.current) ringLight.current.intensity = 0.42 * glow * plan.spot;

    // ── The same light, for the page ───────────────────────────────────────────────────────────────────
    const lx = 0.62 + 0.8 * (swing / LIGHT_SWING.az), ly = -0.8 + 0.3 * st.light.y;
    const angle = (Math.atan2(-lx, ly) * 180) / Math.PI + 360;
    const subjectX = 0.5 + c.sx;
    if (Math.abs(angle - st.out.angle) > 0.2 || Math.abs(subjectX - st.out.sx) > 1e-3) {
      st.out.angle = angle; st.out.sx = subjectX;
      L.onLight(angle % 360, subjectX);
    }

    if (busy && state.frameloop === 'demand') invalidate();
  });

  const onModel = useCallback((m: LoadedModel) => {
    const node = m.scene.getObjectByName('Knob');
    knob.current = node ? { node, base: node.rotation.y } : null;
    setLoaded(true);
    onLoaded();
    invalidate();
  }, [onLoaded, invalidate]);
  const onParts = useCallback((_: unknown, core: PartControllerCore) => {
    let mat: MeshStandardMaterial | null = null;
    core.root.getObjectByName('StatusLight')?.traverse((o) => { if ((o as Mesh).isMesh && !mat) mat = (o as Mesh).material as MeshStandardMaterial; });
    ring.current = mat;
    invalidate();
  }, [invalidate]);
  // The ring material is a PartController clone (the cached original is never touched).
  const overrides = useMemo(() => ({ 'material:LightEmissive': { emissiveIntensity: 1.7 } }) as const, []);

  const plinth = useMemo(buildPlinthGeometry, []);
  const stone = useMemo(buildStoneTextures, []);
  const contact = useMemo(buildContactShadow, []);
  useEffect(() => () => { plinth.dispose(); stone.map.dispose(); stone.roughness.dispose(); contact.dispose(); }, [plinth, stone, contact]);

  return (
    <>
      <fog attach="fog" args={['#14110d', 10.5, 27]} />
      <LightingRig ref={lights} preset={NIGHT} shadow="none" shadowRadius={1.7} />
      <primitive object={spotTarget} position={[0.55, 1.05, 0]} />
      <spotLight ref={spot} position={[1.9, 4.9, 2.4]} angle={0.3} penumbra={0.85} decay={2} intensity={0} color="#ffe9d4" target={spotTarget} />
      {/* The plinth: a filleted drum whose sides fade into the dark; honed-stone top that takes the key's shadow. */}
      <mesh geometry={plinth} receiveShadow>
        <meshStandardMaterial color="#4a443d" vertexColors transparent map={stone.map} roughnessMap={stone.roughness} roughness={1} metalness={0} envMapIntensity={0.9} />
      </mesh>
      <group ref={turntable}>
        <mesh rotation-x={-Math.PI / 2} position-y={0.004} renderOrder={1} raycast={() => null}>
          <planeGeometry args={SHADOW_PLANE} />
          <meshBasicMaterial map={contact} transparent depthWrite={false} toneMapped={false} />
        </mesh>
        <pointLight ref={ringLight} position={KNOB_LIGHT.position} distance={2.2} decay={2} color={RING_LIGHT} intensity={0} />
        <ModelBoundary resetKey={variantUrl} onError={onError}>
          <Suspense fallback={null}>
            <ModelRig url={variantUrl} onModel={onModel} onParts={onParts} overrides={overrides} player={player} ambient={ambience && !reduced} onError={onError} />
          </Suspense>
        </ModelBoundary>
      </group>
    </>
  );
}

/** The speaker, its material controller (clones the ring material) and the LightPulse clip. */
function ModelRig({ url, onModel, onParts, overrides, player, ambient, onError }: {
  url: string; onModel: (m: LoadedModel) => void; onError: (e: Error) => void; onParts: (p: unknown, c: PartControllerCore) => void;
  overrides: Readonly<Record<string, { emissiveIntensity: number }>>; player: MutableRefObject<AnimationPlayerHandle | null>; ambient: boolean;
}) {
  const [model, setModel] = useState<LoadedModel | null>(null);
  return (
    <>
      <Model src={url} scale={10} castShadow onLoaded={(m) => { setModel(m); onModel(m); }} onError={onError} />
      <PartController root={model?.scene ?? null} overrides={overrides} onReady={onParts} />
      <AnimationPlayer ref={player} root={model?.scene ?? null} clips={model?.animations ?? []} clip="LightPulse" loop autoPlay={ambient} />
    </>
  );
}

'use client';
/**
 * The stage's chrome button (Skip intro / Pause light), with weight:
 *  - press depth (technique adapted from press-depth-button): the face drops and its contact shadow tightens within a
 *    frame; letting go springs it back on a CSS linear() curve sampled from the `press` spring token;
 *  - magnetism on fine pointers (adapted from magnetic-button): inside a small field the body leans towards the
 *    pointer and the label leans further (depth); leaving the field hands it to the `release` spring. Off for touch
 *    and reduced motion, where the button keeps its hover, focus and pressed states.
 */
import { useEffect, useRef, useState, useSyncExternalStore, type KeyboardEvent, type ReactNode } from 'react';
import { spring as SPRING, stepSpring, useRafLoop, useStudioMotion } from '../../../motion';
import type { Axis } from './stage';
import styles from './styles.module.css';

const FINE = '(hover: hover) and (pointer: fine)';
const subscribe = (cb: () => void) => {
  if (typeof window === 'undefined' || !window.matchMedia) return () => {};
  const m = window.matchMedia(FINE);
  m.addEventListener('change', cb);
  return () => m.removeEventListener('change', cb);
};
const snapshot = () => typeof window !== 'undefined' && !!window.matchMedia && window.matchMedia(FINE).matches;
/** Field around the pill (px) and how far body and label may travel. */
const FIELD = 56, BODY = 7, LABEL = 2.5;

export function MagneticPill({ children, onClick, pressed: ariaPressed }: { children: ReactNode; onClick: () => void; pressed?: boolean }) {
  const { reduced } = useStudioMotion();
  const fine = useSyncExternalStore(subscribe, snapshot, () => false);
  const enabled = fine && !reduced;
  const anchor = useRef<HTMLSpanElement>(null);
  const body = useRef<HTMLButtonElement>(null);
  const label = useRef<HTMLSpanElement>(null);
  const m = useRef({ bx: { x: 0, v: 0 } as Axis, by: { x: 0, v: 0 } as Axis, lx: { x: 0, v: 0 } as Axis, ly: { x: 0, v: 0 } as Axis, dx: 0, dy: 0, w: 0, near: false });
  const [active, setActive] = useState(false);
  const [down, setDown] = useState(false);

  useEffect(() => {
    if (!enabled) {
      m.current = { ...m.current, bx: { x: 0, v: 0 }, by: { x: 0, v: 0 }, lx: { x: 0, v: 0 }, ly: { x: 0, v: 0 }, near: false };
      if (body.current) body.current.style.transform = '';
      if (label.current) label.current.style.transform = '';
      setActive(false);
      return;
    }
    const onMove = (e: PointerEvent) => {
      if (e.pointerType === 'touch') return;
      const r = anchor.current?.getBoundingClientRect();
      if (!r) return;
      const s = m.current;
      s.dx = e.clientX - (r.left + r.width / 2);
      s.dy = e.clientY - (r.top + r.height / 2);
      const cap = r.height / 2;
      const edge = Math.max(0, Math.hypot(Math.max(0, Math.abs(s.dx) - (r.width / 2 - cap)), s.dy) - cap);
      const near = edge < FIELD;
      s.w = near ? 1 - Math.min(1, edge / FIELD) ** 2 : 0;
      if (near || s.near) { s.near = near; setActive(true); }
    };
    window.addEventListener('pointermove', onMove, { passive: true });
    return () => window.removeEventListener('pointermove', onMove);
  }, [enabled]);

  useRafLoop(anchor, (dt) => {
    const s = m.current;
    const tx = s.near ? BODY * Math.tanh((s.dx * 0.32 * s.w) / BODY) : 0;
    const ty = s.near ? BODY * Math.tanh((s.dy * 0.32 * s.w) / BODY) : 0;
    const cfg = s.near ? SPRING.settle : SPRING.release;
    stepSpring(s.bx, tx, cfg, dt); stepSpring(s.by, ty, cfg, dt);
    stepSpring(s.lx, (tx / BODY) * LABEL, cfg, dt); stepSpring(s.ly, (ty / BODY) * LABEL, cfg, dt);
    if (body.current) body.current.style.transform = `translate3d(${s.bx.x.toFixed(2)}px, ${s.by.x.toFixed(2)}px, 0)`;
    if (label.current) label.current.style.transform = `translate3d(${s.lx.x.toFixed(2)}px, ${s.ly.x.toFixed(2)}px, 0)`;
    const still = [s.bx, s.by, s.lx, s.ly].every((a) => Math.abs(a.v) < 0.02) && Math.abs(s.bx.x - tx) < 0.02 && Math.abs(s.by.x - ty) < 0.02;
    if (still && !s.near) setActive(false);
  }, active && enabled);

  const press = () => setDown(true);
  const lift = () => setDown(false);
  const onKeyDown = (e: KeyboardEvent<HTMLButtonElement>) => { if ((e.key === ' ' || e.key === 'Enter') && !e.repeat) press(); };
  const onKeyUp = (e: KeyboardEvent<HTMLButtonElement>) => { if (e.key === ' ' || e.key === 'Enter') lift(); };

  return (
    <span ref={anchor} className={styles.pillAnchor}>
      <button
        ref={body} type="button" className={styles.pill} data-pressed={down || undefined} aria-pressed={ariaPressed}
        onPointerDown={(e) => { if (e.button === 0) press(); }} onPointerUp={lift} onPointerLeave={lift} onPointerCancel={lift}
        onKeyDown={onKeyDown} onKeyUp={onKeyUp} onBlur={lift} onClick={onClick}
      >
        <span className={styles.pillFace}><span ref={label} className={styles.pillLabel}>{children}</span></span>
      </button>
    </span>
  );
}

/**
 * Pulse Night — the stage: camera shots per chapter, the light plan, the springs that give things weight, and the
 * builders for the plinth and the contact shadow. Plain data and maths (no React), so the Director stays readable.
 *
 * Camera shots are spherical (azimuth/elevation/distance around a focus point) plus a LENS SHIFT: the projection
 * window slides sideways instead of the camera looking away, like a shift lens on a product camera. The speaker is
 * placed opposite the copy without keystoning, and drag, sway and arcs still turn around the speaker itself.
 */
import {
  CanvasTexture, Color, Float32BufferAttribute, LatheGeometry, MathUtils, RepeatWrapping, SRGBColorSpace, Vector2,
} from 'three';
import { springAtRest, type SpringState } from '../../../motion';
import type { LightingPreset } from '../../../three';

export type V3 = [number, number, number];

/**
 * az/el in degrees (az 0 = in front of the speaker, positive = to its right); shift = fraction of the frame;
 * turn = the speaker's own pose on its plinth (degrees), part of the shot like a turntable in a studio.
 */
export interface Shot { az: number; el: number; dist: number; fx: number; fy: number; fz: number; fov: number; sx: number; sy: number; turn: number }
const shot = (az: number, el: number, dist: number, focus: V3, fov: number, shift: [number, number], turn = 0): Shot =>
  ({ az, el, dist, fx: focus[0], fy: focus[1], fz: focus[2], fov, sx: shift[0], sy: shift[1], turn });

export type Framing = 'wide' | 'tall';
/** Shots are authored at these aspect ratios; narrower canvases pull back so the horizontal extent holds. */
export const REFERENCE_ASPECT: Record<Framing, number> = { wide: 1.68, tall: 0.5 };

/**
 * One shot per chapter. Wide: copy left (01), right (02), left (03) — the speaker sits in the other half.
 * Tall (stacked layout): the copy card owns the bottom of the screen, so the speaker is lifted into the top half.
 */
export const SHOTS: Record<Framing, Shot[]> = {
  wide: [
    shot(34, 11, 7.9, [0, 0.66, 0], 27, [0.215, -0.01]),
    shot(-38, 5, 6.4, [-0.1, 0.58, 0.1], 27, [-0.255, 0.02]),
    // 03: the speaker turns half round on its plinth: the dial comes to the near end, the body runs away from the copy
    shot(26, 40, 5.3, [-0.36, 0.98, 0.02], 28, [0.13, -0.02], -180),
  ],
  tall: [
    shot(30, 12, 11.6, [0, 0.66, 0], 31, [0, 0.215]),
    shot(-34, 6, 9.6, [-0.1, 0.58, 0.1], 31, [0, 0.215]),
    shot(26, 44, 7.8, [-0.3, 0.95, 0.02], 31, [0, 0.2], -180),
  ],
};
/** Where the opening move starts: low, far and dark, already on the speaker's side of the frame. */
export const INTRO_FROM: Record<Framing, Shot> = {
  wide: shot(-66, 2, 15.5, [0, 0.6, 0], 22, [0.215, -0.01]),
  tall: shot(-60, 3, 20, [0, 0.6, 0], 26, [0, 0.215]),
};

/** The light plan per chapter (multipliers), blended with the camera. 01 hero key; 02 raking key across the grille; 03 the room goes dark and the dial is lit by a narrow spot and its own ring. */
export interface Light { key: number; keyAz: number; rim: number; env: number; spot: number; ring: number }
export const BEAT_LIGHT: Light[] = [
  { key: 1, keyAz: 0, rim: 1, env: 1, spot: 0, ring: 1 },
  { key: 1.08, keyAz: 0.42, rim: 1.15, env: 0.85, spot: 0, ring: 1 },
  { key: 0.3, keyAz: -0.2, rim: 0.7, env: 0.32, spot: 1, ring: 1.5 },
];

/** Night stage: one warm key from the upper right, a cool rim behind, a faint ember bounce, a dark room. */
export const NIGHT: LightingPreset = {
  label: 'Night stage', description: 'Warm key upper right, cool rim behind, ember bounce, dark room.', exposure: 1,
  ambient: { color: '#fff3e6', intensity: 0.05 },
  key: { color: '#ffe8d1', intensity: 2.9, position: [4.6, 5.0, 3.2] },
  fill: { color: '#ff8a4a', intensity: 0.3, position: [-4.2, 0.9, 2.6] },
  rim: { color: '#b4caff', intensity: 3.3, position: [-3.8, 3.2, -5.2] },
  env: { room: '#060606', intensity: 0.85, panels: [
    { color: '#ffeedd', intensity: 14, position: [4.8, 4.4, 3.4], size: [2.8, 2.0] },
    { color: '#dce7ff', intensity: 16, position: [-5.6, 2.8, -3.2], size: [0.8, 6.0] },
    { color: '#ffffff', intensity: 5, position: [0, 6.6, -1.2], size: [5.5, 1.1] },
    { color: '#f4f1ec', intensity: 2.6, position: [0.8, 3.2, 6.5], size: [6.5, 2.6] },
    { color: '#ff7a3a', intensity: 0.35, position: [-2.5, -2.2, 4.5], size: [6, 1.4] },
  ] },
};
const K = NIGHT.key.position;
/** The key light in spherical terms: the pointer and the drift turn it around the speaker. */
export const KEY_ORBIT = { az: Math.atan2(K[0], K[2]), el: Math.atan2(K[1], Math.hypot(K[0], K[2])), r: Math.hypot(K[0], K[1], K[2]) };
/** How far the pointer swings the key (radians) and how far the camera sways (degrees). */
export const LIGHT_SWING = { az: 0.55, el: 0.12 };
export const SWAY_DEG = { az: 3, el: 2 };

/* ── Easing and blending ─────────────────────────────────────────────────────────────────────────────── */
export const clamp01 = (t: number): number => Math.min(1, Math.max(0, t));
export const smooth = (t: number): number => { const c = clamp01(t); return c * c * (3 - 2 * c); };
export const easeInOut = (t: number): number => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);
export const easeOut = (t: number): number => 1 - (1 - clamp01(t)) ** 3;
export const easeIn = (t: number): number => clamp01(t) ** 2.2;
const mix = (a: number, b: number, t: number): number => a + (b - a) * t;

function lerpShot(a: Shot, b: Shot, k: { az: number; el: number; dist: number; focus: number; fov: number; shift: number }, out: Shot): Shot {
  out.turn = mix(a.turn, b.turn, k.focus);
  out.az = mix(a.az, b.az, k.az); out.el = mix(a.el, b.el, k.el); out.dist = mix(a.dist, b.dist, k.dist);
  out.fx = mix(a.fx, b.fx, k.focus); out.fy = mix(a.fy, b.fy, k.focus); out.fz = mix(a.fz, b.fz, k.focus);
  out.fov = mix(a.fov, b.fov, k.fov); out.sx = mix(a.sx, b.sx, k.shift); out.sy = mix(a.sy, b.sy, k.shift);
  return out;
}

/**
 * The shot for a scroll position. Each chapter is held for the middle of its range and the camera travels in
 * between, with a different move per transition: 01→02 swings round and pulls back on an arc; 02→03 is a crane
 * (it rises first, then turns). `weights` blends the light plan the same way. Reduced motion: no travel, the
 * nearest chapter's shot.
 */
export function shotForProgress(p: number, frame: Framing, reduced: boolean, out: Shot, weights: [number, number, number]): Shot {
  const list = SHOTS[frame];
  const x = clamp01(p) * (list.length - 1);
  if (reduced) {
    const i = Math.round(x);
    Object.assign(out, list[i]);
    weights[0] = i === 0 ? 1 : 0; weights[1] = i === 1 ? 1 : 0; weights[2] = i === 2 ? 1 : 0;
    return out;
  }
  const i = Math.min(list.length - 2, Math.floor(x));
  const k = smooth((x - i - 0.18) / 0.64);
  if (i === 0) {
    lerpShot(list[0], list[1], { az: easeInOut(k), el: k, dist: k, focus: smooth(k), fov: k, shift: easeInOut(k) }, out);
    out.dist += Math.sin(Math.PI * k) * 1.4;
    out.el += Math.sin(Math.PI * k) * 5;
  } else {
    lerpShot(list[1], list[2], { az: easeIn(k), el: easeOut(k), dist: smooth(k), focus: smooth(k), fov: k, shift: easeInOut(k) }, out);
    out.dist += Math.sin(Math.PI * k) * 0.6;
  }
  weights[0] = i === 0 ? 1 - k : 0; weights[1] = i === 0 ? k : 1 - k; weights[2] = i === 1 ? k : 0;
  return out;
}

/** The opening move from INTRO_FROM to the first chapter: a wide arc that ends exactly on the held shot. */
export function introShot(t: number, from: Shot, to: Shot, out: Shot): Shot {
  const e = easeInOut(clamp01(t));
  lerpShot(from, to, { az: e, el: easeOut(t) * 0.35 + e * 0.65, dist: easeOut(t * 1.1), focus: smooth(t), fov: e, shift: 1 }, out);
  out.el += Math.sin(Math.PI * e) * 6;
  return out;
}

export function blendLight(w: readonly number[], out: Light): Light {
  out.key = 0; out.keyAz = 0; out.rim = 0; out.env = 0; out.spot = 0; out.ring = 0;
  BEAT_LIGHT.forEach((b, i) => {
    out.key += b.key * w[i]; out.keyAz += b.keyAz * w[i]; out.rim += b.rim * w[i];
    out.env += b.env * w[i]; out.spot += b.spot * w[i]; out.ring += b.ring * w[i];
  });
  return out;
}

/* ── Weight: springs that keep the hand's velocity ───────────────────────────────────────────────────── */
/* Stepped with `stepSpring` from motion/; `atRest` is this stage's tolerance (velocity eps per 1/4 s). */
export type Axis = SpringState;
export const atRest = (a: Axis, target: number, eps = 1e-3): boolean => springAtRest(a, target, { restDelta: eps, restSpeed: eps * 4 });

/** Critically damped follow (SmoothDamp); `vel` is mutated. */
export function damp(cur: number, goal: number, vel: { v: number }, smoothTime: number, dt: number): number {
  const omega = 2 / Math.max(1e-4, smoothTime), x = omega * dt, k = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  const change = cur - goal, temp = (vel.v + omega * change) * dt;
  vel.v = (vel.v - omega * temp) * k;
  return goal + (change + temp) * k;
}

/** Rubber band: 1:1 up to `free`, then resistance that never passes `limit`. */
export function softLimit(x: number, free: number, limit: number): number {
  const a = Math.abs(x);
  if (a <= free) return x;
  return Math.sign(x) * (free + (limit - free) * Math.tanh((a - free) / (limit - free)));
}

/** Release velocity from the last ~90 ms of samples; a pointer that stopped before letting go throws nothing. */
export function releaseVelocity(samples: readonly { t: number; x: number }[], now: number): number {
  if (samples.length < 2) return 0;
  const last = samples[samples.length - 1];
  if (now - last.t > 70) return 0;
  let first = samples[0];
  for (let i = samples.length - 1; i >= 0; i--) { first = samples[i]; if (last.t - samples[i].t >= 90) break; }
  const dt = (last.t - first.t) / 1000;
  return dt > 0.008 ? (last.x - first.x) / dt : 0;
}

/** The dial's detents: the angle sticks near each notch and hops between them (a notched encoder). */
export const DETENT = (2 * Math.PI) / 30;
export const VOLUME = { start: 12, max: 30 };
export function detented(angle: number, strength = 0.78): number {
  return angle - (DETENT / (2 * Math.PI)) * strength * Math.sin((2 * Math.PI * angle) / DETENT);
}
/** Clockwise from above (negative Y rotation) turns the volume up. */
export const volumeAt = (angle: number): number => Math.min(VOLUME.max, Math.max(0, VOLUME.start + Math.round(-angle / DETENT)));

/* ── The plinth and its contact shadow ───────────────────────────────────────────────────────────────── */
export const PLINTH = { radius: 1.74, height: 0.7, fillet: 0.08 };

/**
 * A low drum with a filleted top edge (LatheGeometry). Vertex colours (RGBA) darken the side and fade it out from the
 * fillet down, so the plinth has a soft edge that dissolves into the stage instead of a hard rim. Planar UVs on the
 * top, cylindrical UVs on the side (a whole number of repeats around, so there is no seam).
 */
export function buildPlinthGeometry(): LatheGeometry {
  const { radius: R, height: H, fillet: f } = PLINTH;
  const pts: Vector2[] = [new Vector2(0, 0), new Vector2(R * 0.5, 0), new Vector2(R - f, 0)];
  for (let i = 1; i <= 8; i++) { const a = (i / 8) * (Math.PI / 2); pts.push(new Vector2(R - f + f * Math.sin(a), -f + f * Math.cos(a))); }
  for (let i = 1; i <= 4; i++) pts.push(new Vector2(R, -f - ((H - f) * i) / 4));
  const geo = new LatheGeometry(pts, 112);
  const side = pts.map((p) => smooth((-p.y - f * 0.6) / (H - f)));
  const pos = geo.getAttribute('position');
  const colors = new Float32Array(pos.count * 4);
  const uvs = new Float32Array(pos.count * 2);
  const around = Math.round(Math.PI); // the top's texel density, a whole number of repeats around the side
  for (let v = 0; v < pos.count; v++) {
    const k = side[v % pts.length];
    const c = MathUtils.lerp(1, 0.3, k);
    colors[v * 4] = c; colors[v * 4 + 1] = c; colors[v * 4 + 2] = c; colors[v * 4 + 3] = 1 - k;
    const x = pos.getX(v), y = pos.getY(v), z = pos.getZ(v);
    if (y > -f * 0.6) { uvs[v * 2] = x / (2 * R) + 0.5; uvs[v * 2 + 1] = z / (2 * R) + 0.5; }
    else { uvs[v * 2] = ((Math.atan2(z, x) + Math.PI) / (2 * Math.PI)) * around; uvs[v * 2 + 1] = -y / (2 * R); }
  }
  geo.setAttribute('color', new Float32BufferAttribute(colors, 4));
  geo.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
  return geo;
}

function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

/** Honed-stone surface: a seeded value-noise albedo (sRGB) and roughness (linear) pair, 256 px, tiling. */
export function buildStoneTextures(): { map: CanvasTexture; roughness: CanvasTexture } {
  const N = 256, cell = 16, rand = rng(7);
  const grid = Array.from({ length: (N / cell + 1) ** 2 }, () => rand());
  const g = (x: number, y: number) => grid[(y % (N / cell)) * (N / cell + 1) + (x % (N / cell))];
  const make = (fn: (n: number, fine: number) => number, srgb: boolean) => {
    const c = document.createElement('canvas'); c.width = N; c.height = N;
    const ctx = c.getContext('2d');
    if (ctx) {
      const img = ctx.createImageData(N, N);
      for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
        const gx = Math.floor(x / cell), gy = Math.floor(y / cell), tx = smooth((x % cell) / cell), ty = smooth((y % cell) / cell);
        const n = mix(mix(g(gx, gy), g(gx + 1, gy), tx), mix(g(gx, gy + 1), g(gx + 1, gy + 1), tx), ty);
        const v = Math.round(255 * clamp01(fn(n, rand())));
        const o = (y * N + x) * 4; img.data[o] = v; img.data[o + 1] = v; img.data[o + 2] = v; img.data[o + 3] = 255;
      }
      ctx.putImageData(img, 0, 0);
    }
    const t = new CanvasTexture(c);
    t.wrapS = t.wrapT = RepeatWrapping; t.repeat.set(3, 3);
    if (srgb) t.colorSpace = SRGBColorSpace;
    return t;
  };
  return {
    map: make((n, fine) => 0.9 + n * 0.08 + (fine - 0.5) * 0.05, true),
    roughness: make((n, fine) => 0.52 + n * 0.16 + (fine - 0.5) * 0.08, false),
  };
}

/** Footprint of the speaker (scene units) for the contact shadow: body, and the four rubber feet. */
const FOOT: V3[] = [[-0.74, 0, 0.24], [0.74, 0, 0.24], [-0.74, 0, -0.24], [0.74, 0, -0.24]];
export const SHADOW_PLANE: [number, number] = [3.6, 1.8];

/**
 * Two-layer contact shadow drawn once on a canvas: a wide soft occlusion and a tight core, plus the feet. Shadows are
 * drawn with `shadowBlur` from shapes kept off-canvas, which every 2D canvas supports (unlike `ctx.filter`).
 */
export function buildContactShadow(): CanvasTexture {
  const W = 512, H = 256, ppu = W / SHADOW_PLANE[0];
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const ctx = c.getContext('2d');
  const blurred = (draw: (x: number, y: number) => void, blurUnits: number, alpha: number) => {
    if (!ctx) return;
    ctx.save();
    ctx.shadowColor = `rgba(0,0,0,${alpha})`;
    ctx.shadowBlur = blurUnits * ppu;
    ctx.shadowOffsetX = W * 2;
    ctx.fillStyle = '#000';
    ctx.beginPath(); draw(W / 2 - W * 2, H / 2 + 0.03 * ppu); ctx.fill();
    ctx.restore();
  };
  const rrect = (w: number, h: number, r: number) => (cx: number, cy: number) => ctx?.roundRect(cx - (w * ppu) / 2, cy - (h * ppu) / 2, w * ppu, h * ppu, r * ppu);
  blurred(rrect(2.5, 1.12, 0.48), 0.34, 0.5);
  blurred(rrect(2.2, 0.8, 0.34), 0.09, 0.5);
  for (const [x, , z] of FOOT) blurred((cx, cy) => ctx?.arc(cx + x * ppu, cy + z * ppu, 0.09 * ppu, 0, Math.PI * 2), 0.03, 0.65);
  const t = new CanvasTexture(c);
  t.colorSpace = SRGBColorSpace;
  return t;
}

export const RING_LIGHT = new Color('#7fe8ff');

/* Pulse Night Edition — black stage, one warm key, editorial serif against a heavy grotesque.
   One light: the scene writes --light-angle (the direction the light travels, CSS gradient convention) and
   --subject-x (where the speaker stands); sheens, lit edges and drop shadows here follow the same angle. */
.root {
  --light-angle: 218deg;
  --subject-x: 72%;
  --ldx: sin(var(--light-angle));
  --ldy: calc(-1 * cos(var(--light-angle)));
  background: var(--mk-bg, #0e0e0c);
}

.scene { position: relative; height: 300svh; }
.sticky {
  position: sticky;
  top: 44px;
  height: calc(100svh - 44px);
  overflow: hidden;
  background:
    radial-gradient(36% 52% at var(--subject-x, 72%) 56%, #2e251b 0%, rgb(34 28 21 / 0.55) 46%, rgb(14 14 12 / 0) 100%),
    radial-gradient(130% 95% at 50% 40%, #15130f 0%, #0e0e0c 72%);
}
.sticky canvas { cursor: grab; }
.sticky canvas[data-dragging] { cursor: grabbing; }
.sticky canvas:focus-visible { outline: 2px solid var(--mk-focus, #8ab4ff); outline-offset: -4px; }

/* Fallback still: it slides to the side opposite the copy, like the camera does. */
.poster {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(48%, 600px);
  transform: translate(calc(-50% + var(--poster-shift, 22cqi)), -50%);
  transition: transform var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease);
}
.root[data-beat='1'] { --poster-shift: -24cqi; }
.loading { position: absolute; right: 16px; bottom: 16px; margin: 0; color: var(--mk-ink-muted, #a8a59a); }

/* ── Chrome ─────────────────────────────────────────────────────────────────────────────────────────── */
.beats { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
.chrome { position: sticky; top: 44px; height: 0; z-index: 3; }
.chromeRow {
  position: absolute;
  top: 14px;
  left: 16px;
  right: 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.chromeRow button, .nav button, .copy button { pointer-events: auto; }

/* The pill: magnetic body, pressable face, lit from the scene's key (edge highlight + shadow on the far side). */
.pillAnchor { position: relative; display: inline-grid; pointer-events: auto; }
.pill {
  position: relative;
  display: inline-grid;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: none;
  color: var(--mk-ink, #f3f0e8);
  font: 500 13px/1 var(--mk-font-text, system-ui, sans-serif);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.pill:focus-visible { outline: 2px solid var(--mk-focus, #8ab4ff); outline-offset: 3px; }
.pillFace {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 0 17px;
  border-radius: inherit;
  background: linear-gradient(var(--light-angle), rgb(255 247 234 / 0.16), rgb(255 247 234 / 0.03) 62%), rgb(20 19 17 / 0.84);
  box-shadow:
    inset 0 0 0 1px rgb(243 240 232 / 0.24),
    inset calc(var(--ldx) * -1.2px) calc(var(--ldy) * -1.2px) 0 rgb(255 250 240 / 0.2),
    calc(var(--ldx) * 2px) calc(var(--ldy) * 3px) 4px rgb(0 0 0 / 0.4),
    calc(var(--ldx) * 9px) calc(var(--ldy) * 14px) 26px rgb(0 0 0 / 0.42);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  transform: translateY(0) scale(1);
  transition:
    transform var(--release-dur, 520ms) var(--release-ease, ease),
    box-shadow var(--release-dur, 520ms) var(--release-ease, ease),
    background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.pillLabel { display: inline-block; }
.pill:hover .pillFace {
  background-color: rgb(30 28 25 / 0.9);
  box-shadow:
    inset 0 0 0 1px rgb(243 240 232 / 0.4),
    inset calc(var(--ldx) * -1.2px) calc(var(--ldy) * -1.2px) 0 rgb(255 250 240 / 0.26),
    calc(var(--ldx) * 3px) calc(var(--ldy) * 5px) 6px rgb(0 0 0 / 0.36),
    calc(var(--ldx) * 13px) calc(var(--ldy) * 20px) 34px rgb(0 0 0 / 0.46);
  transform: translateY(-1px);
}
.pill[data-pressed] .pillFace {
  transform: translateY(1.5px) scale(0.965);
  box-shadow:
    inset 0 0 0 1px rgb(243 240 232 / 0.3),
    inset 0 2px 5px rgb(0 0 0 / 0.45),
    calc(var(--ldx) * 1px) calc(var(--ldy) * 1px) 1px rgb(0 0 0 / 0.5),
    calc(var(--ldx) * 3px) calc(var(--ldy) * 5px) 10px rgb(0 0 0 / 0.3);
  transition:
    transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease),
    box-shadow var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}

.nav {
  position: absolute;
  top: calc(50svh - 100px);
  right: 16px;
  display: none;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  isolation: isolate;
}
/* its own soft scrim: the labels stay legible wherever the speaker turns */
.nav::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: -36px -16px -36px -36px;
  pointer-events: none;
  background: radial-gradient(closest-side, rgb(9 9 8 / 0.72), rgb(9 9 8 / 0.4) 60%, rgb(9 9 8 / 0));
}
.navItem {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  min-height: 32px;
  padding: 7px 12px 0 10px;
  border: 0;
  border-radius: 4px;
  background: none;
  color: var(--mk-ink-muted, #a8a59a);
  font-size: 13px;
  cursor: pointer;
  transition: color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), transform var(--release-dur, 520ms) var(--release-ease, ease);
}
.navItem::after {
  content: '';
  position: absolute;
  top: 5px;
  right: 0;
  bottom: 5px;
  width: 2px;
  border-radius: 1px;
  background: var(--mk-line, #f3f0e826);
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), transform var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease), box-shadow var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
}
.navItem:hover { color: var(--mk-ink, #f3f0e8); }
.navItem:hover::after { background: var(--mk-line-strong, #f3f0e8); transform: scaleX(1.5); }
.navItem:active { transform: translateX(2px); transition: transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease); }
.navItem[aria-current='step'] { color: var(--mk-ink, #f3f0e8); }
.navItem[aria-current='step']::after { background: var(--mk-signal, #ff5a2b); transform: scaleX(1.5); box-shadow: 0 0 10px rgb(255 90 43 / 0.55); }
.navItem:focus-visible { outline: 2px solid var(--mk-focus, #8ab4ff); outline-offset: 2px; }

/* ── Chapters ───────────────────────────────────────────────────────────────────────────────────────── */
.beat {
  display: flex;
  align-items: flex-end;
  height: 100svh;
  padding: 72px 16px 20px;
  scroll-margin-top: 44px;
}
/* Stacked: a dark glass card at the bottom of each chapter, the speaker framed above it. */
.copy {
  position: relative;
  isolation: isolate;
  display: grid;
  gap: 14px;
  width: 100%;
  max-width: 31rem;
  padding: 18px;
  border: 1px solid var(--mk-line, #f3f0e826);
  border-radius: var(--mk-radius-m, 10px);
  background: rgb(14 14 12 / 0.86);
  -webkit-backdrop-filter: blur(14px) saturate(1.1);
  backdrop-filter: blur(14px) saturate(1.1);
  box-shadow: inset 0 1px 0 rgb(255 250 240 / 0.06), 0 18px 40px rgb(0 0 0 / 0.45);
}

/* The headline and titles are lit from the scene's key: a sheen that turns with --light-angle. */
.headline :global(h2), .headline h2 { font-size: clamp(2.3rem, 7.2cqi, 5.4rem); max-width: 11ch; color: var(--mk-ink, #f3f0e8); }
.headline :global([data-word]), .title {
  background-image: linear-gradient(var(--light-angle), #fffaf2 0%, #f3efe6 32%, #dcd5c7 70%, #bfb6a6 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
@media (forced-colors: active) {
  .headline :global([data-word]), .title { background: none; -webkit-text-fill-color: currentColor; }
}
.title {
  margin: 0;
  color: var(--mk-ink, #f3f0e8);
  font-family: var(--mk-font-display, system-ui, sans-serif);
  font-weight: 700;
  font-size: clamp(2rem, 5.6cqi, 4rem);
  line-height: 0.98;
  letter-spacing: -0.035em;
}
.eyebrow { margin: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 12px; letter-spacing: 0.08em; color: var(--mk-signal, #ff5a2b); }
.body { margin: 0; max-width: 36ch; font-size: 16px; line-height: 1.6; color: var(--mk-ink-muted, #a8a59a); }
.hint { display: flex; align-items: center; gap: 12px; margin: 6px 0 0; color: var(--mk-ink-muted, #a8a59a); }
.rule {
  display: inline-block;
  flex: none;
  width: 48px;
  height: 1px;
  background: linear-gradient(calc(var(--light-angle) - 128deg), rgb(243 240 232 / 0.35), #fffaf2);
}

/* The dial's twin: two keycaps around a readout. Pressed faces drop onto their side band; release springs. */
.dialRow { display: flex; align-items: center; gap: 14px; margin-top: 4px; }
.key {
  position: relative;
  display: inline-grid;
  flex: none;
  width: 46px;
  height: 50px;
  margin: 0;
  padding: 0 0 5px;
  border: 0;
  border-radius: 50%;
  background: none;
  color: var(--mk-ink, #f3f0e8);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.key::before {
  content: '';
  position: absolute;
  inset: 5px 0 0;
  border-radius: 50%;
  background: #0a0908;
  box-shadow: inset 0 0 0 1px rgb(243 240 232 / 0.12), calc(var(--ldx) * 4px) calc(var(--ldy) * 6px) 12px rgb(0 0 0 / 0.55);
}
.keyFace {
  position: relative;
  display: grid;
  place-items: center;
  height: 45px;
  border-radius: 50%;
  background: radial-gradient(circle at calc(50% - var(--ldx) * 22%) calc(50% - var(--ldy) * 22%), #45403a, #27241f 62%, #1b1916);
  box-shadow: inset 0 0 0 1px rgb(243 240 232 / 0.18), inset calc(var(--ldx) * -1px) calc(var(--ldy) * -1px) 0 rgb(255 250 240 / 0.16);
  font: 500 21px/1 var(--mk-font-text, system-ui, sans-serif);
  transform: translateY(0);
  transition: transform var(--release-dur, 520ms) var(--release-ease, ease), background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.key:hover:not(:disabled) .keyFace { transform: translateY(-1px); box-shadow: inset 0 0 0 1px rgb(243 240 232 / 0.36), inset calc(var(--ldx) * -1px) calc(var(--ldy) * -1px) 0 rgb(255 250 240 / 0.22); }
.key:active:not(:disabled) .keyFace { transform: translateY(4px); transition: transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease); }
.key:focus-visible { outline: 2px solid var(--mk-focus, #8ab4ff); outline-offset: 3px; }
.key:disabled { cursor: not-allowed; }
.key:disabled .keyFace { transform: translateY(5px); color: var(--mk-ink-muted, #a8a59a); }
.readout { display: grid; gap: 7px; margin: 0; min-width: 92px; }
.readoutValue { font: 600 28px/1 var(--mk-font-mono, ui-monospace, monospace); font-variant-numeric: tabular-nums; letter-spacing: -0.02em; color: var(--mk-ink, #f3f0e8); }
.meter { display: block; height: 3px; overflow: hidden; border-radius: 2px; background: var(--mk-line, #f3f0e826); }
.meter > span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #4cd3ea, #a8f4ff);
  box-shadow: 0 0 8px rgb(127 232 255 / 0.6);
  transform-origin: 0 50%;
  transition: transform var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}

.link {
  color: var(--mk-ink, #f3f0e8);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
  transition: color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), text-decoration-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.link:hover { color: var(--mk-signal, #ff5a2b); text-decoration-thickness: 2px; }
.link:active { color: var(--mk-ink-muted, #a8a59a); }

/* ── Split layout: copy beside the speaker, on a directional scrim (darkest away from the speaker). ──── */
@container (width >= 48rem) {
  .sticky {
    background:
      radial-gradient(32% 56% at var(--subject-x, 72%) 55%, #30261b 0%, rgb(36 29 21 / 0.55) 46%, rgb(14 14 12 / 0) 100%),
      radial-gradient(130% 95% at 50% 40%, #15130f 0%, #0e0e0c 72%);
  }
  .beat { align-items: center; padding: 96px 8% 48px; }
  .beatRight { justify-content: flex-end; padding-right: 12%; }
  .copy { max-width: min(31rem, 42cqi); padding: 0; border: 0; border-radius: 0; background: none; -webkit-backdrop-filter: none; backdrop-filter: none; box-shadow: none; }
  .copy::before {
    content: '';
    position: absolute;
    z-index: -1;
    inset: -30% -34% -30% -62%;
    pointer-events: none;
    background: radial-gradient(closest-side, rgb(9 9 8 / 0.84) 0%, rgb(9 9 8 / 0.72) 42%, rgb(9 9 8 / 0.36) 72%, rgb(9 9 8 / 0) 100%);
  }
  .beatRight .copy::before { inset: -30% -62% -30% -34%; }
  .nav { display: flex; }
}
@container (width < 48rem) {
  .poster { top: 30%; width: min(78%, 420px); transform: translate(-50%, -50%); }
}
